diff --git a/sql/sql_parse.cc b/sql/sql_parse.cc
index 2e2a6f4d1b17..f6e94c118af6 100644
--- a/sql/sql_parse.cc
+++ b/sql/sql_parse.cc
@@ -3664,8 +3664,6 @@ mysql_execute_command(THD *thd)
       my_error(ER_WRONG_DB_NAME, MYF(0), lex->name);
       break;
     }
-    if (check_access(thd,SELECT_ACL,lex->name,0,1,0,is_schema_db(lex->name)))
-      break;
     res=mysqld_show_create_db(thd,lex->name,&lex->create_info);
     break;
   }
diff --git a/sql/sql_show.cc b/sql/sql_show.cc
index 025c344b86fc..badc15f2ab50 100644
--- a/sql/sql_show.cc
+++ b/sql/sql_show.cc
@@ -482,12 +482,6 @@ bool mysqld_show_create_db(THD *thd, char *dbname,
   Protocol *protocol=thd->protocol;
   DBUG_ENTER("mysql_show_create_db");

-  if (check_db_name(dbname))
-  {
-    my_error(ER_WRONG_DB_NAME, MYF(0), dbname);
-    DBUG_RETURN(TRUE);
-  }
-
 #ifndef NO_EMBEDDED_ACCESS_CHECKS
   if (test_all_bits(sctx->master_access, DB_ACLS))
     db_access=DB_ACLS;

